// Build a valid allocator suite and install it via valkeySetAllocators.
// Requirements enforced:
//  - fns non-NULL and all members valid function pointers
//  - functions follow libc-like semantics
// We also restore the previous allocator immediately to avoid leaking global state across fuzz calls.

// libc-backed implementations (no captures so they decay to function pointers):
auto my_malloc = +[](size_t n) -> void * {
    // Keep allocations reasonably small for fuzz performance if library uses these.
    if (n > 2048) n = 2048;
    return std::malloc(n);
};
auto my_calloc = +[](size_t nmemb, size_t size) -> void * {
    // Avoid overflow and keep sizes reasonable.
    if (size != 0 && nmemb > (size_t)(2048 / size)) nmemb = (size_t)(2048 / (size ? size : 1));
    return std::calloc(nmemb, size);
};
auto my_realloc = +[](void *p, size_t n) -> void * {
    if (n > 2048) n = 2048;
    return std::realloc(p, n);
};
auto my_strdup = +[](const char *s) -> char * {
    if (!s) return (char *)NULL; // strdup(NULL) is UB; follow requirement that caller passes valid string
    size_t len = std::strlen(s);
    if (len > 2048) len = 2048; // cap
    char *out = (char *)std::malloc(len + 1);
    if (!out) return (char *)NULL;
    std::memcpy(out, s, len);
    out[len] = '\0';
    return out;
};
auto my_free = +[](void *p) -> void { std::free(p); };

valkeyAllocFuncs fns;
fns.mallocFn  = my_malloc;
fns.callocFn  = my_calloc;
fns.reallocFn = my_realloc;
fns.strdupFn  = my_strdup;
fns.freeFn    = my_free;

// Call target function
