# Helpers to build RESP2/RESP3-like replies

def resp_simple(prefix: bytes, text: str) -> bytes:
    return prefix + text.encode("utf-8", "strict") + b"\r\n"

def resp_bulk(s: bytes) -> bytes:
    # $<len>\r\n<data>\r\n
    return b"$" + str(len(s)).encode() + b"\r\n" + s + b"\r\n"

def resp_null_bulk() -> bytes:
    return b"$-1\r\n"

def resp_integer(n: int) -> bytes:
    return b":" + str(n).encode() + b"\r\n"

def resp_array(items: List[bytes]) -> bytes:
    # *<n>\r\n<item1><item2>...
    return b"*" + str(len(items)).encode() + b"\r\n" + b"".join(items)

def resp_null_array() -> bytes:
    return b"*-1\r\n"

def resp_bool(v: bool) -> bytes:
