    return b"=" + str(len(data)).encode() + b"\r\n" + data + b"\r\n"

def resp_blob_error(vtype3: bytes, payload: bytes) -> bytes:
    # RESP3 blob error: !<len>\r\n<3bytes>:<payload>\r\n
    if len(vtype3) != 3:
        vtype3 = vtype3[:3].ljust(3, b" ")
    data = vtype3 + b":" + payload
    return b"!" + str(len(data)).encode() + b"\r\n" + data + b"\r\n"

def resp_map(items: List[Tuple[bytes, bytes]]) -> bytes:
    # RESP3 map: %<n>\r\n<key><value>...
    out = [b"%" + str(len(items)).encode() + b"\r\n"]
    for k, v in items:
        out.append(k)
        out.append(v)
    return b"".join(out)

def resp_set(items: List[bytes]) -> bytes:
    # RESP3 set: ~<n>\r\n<item>...
    return b"~" + str(len(items)).encode() + b"\r\n" + b"".join(items)

def resp_push(items: List[bytes]) -> bytes:
    # RESP3 push: ><n>\r\n<item>...
    return b">" + str(len(items)).encode() + b"\r\n" + b"".join(items)

# Generators for various interesting values

def rand_ascii(r: random.Random, min_len=0, max_len=64) -> bytes:
    n = r.randint(min_len, max_len)
    alphabet = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-./:@ "
    return bytes(r.choice(alphabet) for _ in range(n))

def rand_binary(r: random.Random, min_len=0, max_len=128) -> bytes:
    n = r.randint(min_len, max_len)
    return r.randbytes(n)

def gen_varied_bulk(r: random.Random) -> bytes:
    choice = r.randrange(6)
    if choice == 0:
        return resp_bulk(b"")
    if choice == 1:
        return resp_bulk(rand_ascii(r, 1, 64))
    if choice == 2:
        return resp_bulk(rand_binary(r, 1, 128))
    if choice == 3:
        return resp_null_bulk()
    if choice == 4:
        # Large bulk (but bounded) to exercise size handling
        return resp_bulk(rand_binary(r, 256, 1024))
    # UTF-8 with multi-byte
    s = "π/测试/🙂".encode("utf-8")
    return resp_bulk(s)

def gen_scalar(r: random.Random) -> bytes:
    t = r.randrange(9)
    if t == 0:
        return resp_simple(b"+", "OK")
    if t == 1:
        return resp_simple(b"-", "ERR some error")
    if t == 2:
        return resp_integer(r.randint(-2**31, 2**31 - 1))
    if t == 3:
        return gen_varied_bulk(r)
    if t == 4:
        return resp_bool(r.choice([True, False]))
    if t == 5:
        vals = [0.0, 1.0, -1.0, 3.1415926535, 1e308, -1e308, float('inf'), float('-inf'), float('nan')]
        return resp_double(r.choice(vals))
    if t == 6:
        return resp_bigint(r.randint(2**63, 2**65))
    if t == 7:
        return resp_verbatim(b"txt", rand_ascii(r, 0, 40))
    return resp_blob_error(b"ERR", rand_ascii(r, 0, 40))

def gen_array_mixed(r: random.Random, depth=0) -> bytes:
    if depth > 2:
        # Limit depth to keep size small
        n = r.randint(0, 6)
        items = [gen_scalar(r) for _ in range(n)]
        return resp_array(items)
    kind = r.randrange(6)
    if kind == 0:
        return resp_null_array()
    n = r.randint(0, 6)
    items: List[bytes] = []
    for _ in range(n):
        which = r.randrange(4)
        if which == 0:
            items.append(gen_scalar(r))
        elif which == 1:
            items.append(gen_array_mixed(r, depth + 1))
        elif which == 2:
            # Nested map encoded with RESP3 within array
            kvn = r.randint(0, 4)
            kvs: List[Tuple[bytes, bytes]] = []
            for _ in range(kvn):
                k = gen_scalar(r)
                v = gen_scalar(r)
                kvs.append((k, v))
            items.append(resp_map(kvs))
        else:
            # Nested set
            sn = r.randint(0, 4)
            sitems = [gen_scalar(r) for _ in range(sn)]
            items.append(resp_set(sitems))
    return resp_array(items)

def gen_map_top(r: random.Random) -> bytes:
    # Build a map with simple keys and various values
    n = r.randint(0, 5)
    kvs: List[Tuple[bytes, bytes]] = []
    for _ in range(n):
        k = gen_scalar(r)
        # Ensure keys are strings/bulk to look like typical RESP3 maps
        if k[:1] not in (b"+", b"$", b"=", b":"):
            k = resp_bulk(rand_ascii(r, 1, 16))
        v_choice = r.randrange(4)
        if v_choice == 0:
            v = gen_scalar(r)
        elif v_choice == 1:
            v = gen_array_mixed(r)
        elif v_choice == 2:
            v = resp_set([gen_scalar(r) for _ in range(r.randint(0, 4))])
        else:
            v = resp_map([(resp_bulk(rand_ascii(r, 1, 8)), gen_scalar(r)) for _ in range(r.randint(0, 3))])
        kvs.append((k, v))
    return resp_map(kvs)

def gen_push_messages(r: random.Random) -> bytes:
    # Construct a PUSH message similar to pub/sub
    chan = resp_bulk(rand_ascii(r, 3, 10))
    payload = gen_varied_bulk(r)
    meta = resp_simple(b"+", "meta")
    return resp_push([chan, payload, meta])


def build_stream(r: random.Random, budget: int) -> bytes:
    parts: List[bytes] = []
    remaining = budget
    # Compose a mix of replies until we fill the budget
    while remaining > 0:
        choice = r.randrange(8)
        if choice == 0:
            chunk = gen_scalar(r)
        elif choice == 1:
            chunk = gen_array_mixed(r)
        elif choice == 2:
            chunk = gen_map_top(r)
        elif choice == 3:
            chunk = gen_push_messages(r)
        elif choice == 4:
            # Pipeline multiple simple replies
            chunk = b"".join(gen_scalar(r) for _ in range(r.randint(2, 6)))
        elif choice == 5:
            # Array of bulk strings (common): e.g., MGET-like reply
            n = r.randint(0, 6)
            items = [gen_varied_bulk(r) for _ in range(n)]
            chunk = resp_array(items)
        elif choice == 6:
            # Integer-heavy
            items = [resp_integer(r.randint(-10**12, 10**12)) for _ in range(r.randint(1, 8))]
            chunk = b"".join(items)
        else:
            # Verbatim / blob error mix
            chunk = b"".join(
                r.choice([
                    resp_verbatim(b"txt", rand_ascii(r, 0, 20)),
                    resp_verbatim(b"mkd", rand_ascii(r, 0, 20)),
                    resp_blob_error(b"ERR", rand_ascii(r, 0, 20)),
                ]) for _ in range(r.randint(1, 4))
            )
        if len(chunk) > remaining:
            # Possibly include a partial final reply to exercise partial feed
            take = r.randint(max(1, remaining // 4), remaining)
            parts.append(chunk[:take])
            remaining -= take
            break
        parts.append(chunk)
        remaining -= len(chunk)
    return b"".join(parts)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Keep under 4096 bytes as required; pick a random target size in a useful range
    target = r.randint(64, 2048)
    stream = build_stream(r, target)

    # Optionally prepend or append benign data to vary prefix selection
    prefix_choice = r.randrange(4)
    if prefix_choice == 0:
        stream = resp_simple(b"+", "PONG") + stream
    elif prefix_choice == 1:
        stream = stream + resp_simple(b"+", "OK")
    # else leave as-is or already diverse

    # Ensure non-empty result
    if not stream:
        stream = resp_simple(b"+", "OK")

    # Final clamp just in case
    return stream[:4096]
